"""Abonnements (ETO Free / Pro / MAX / Ultra) et Espace CEO (éditions privées) : catalogue, prix mensuels / annuels, badge « Actif », marque E.T.O. / E.N.O.S.
dans l'en-tête, couleur de l'offre, mode test (simulation de toutes les versions), éditions privées absentes de l'Abonnement et de l'app grand public."""
from mobile_common import *

errs = []
with sync_playwright() as pw:
    b, ctx = launch(pw); pg = open_app(ctx, errs); pg.set_default_timeout(30000)
    pg.add_style_tag(content="#toasts{display:none!important}")
    brand = lambda: pg.inner_text("#top .brand > span").split("\n")[0].strip()
    check(pg.evaluate("ENOS.plans.current()") == "enos_ceo" and brand() == "E.N.O.S.", "app de test : version réelle E.N.O.S. CEO, en-tête « E.N.O.S. » (%s)" % brand())
    open_tool(pg, "plans"); pg.wait_for_timeout(900)
    cards = pg.evaluate("[...document.querySelectorAll('#tool-plans .pl-card')].map((c) => c.dataset.p)")
    check(cards == ["eto_free", "eto_pro", "eto_max", "eto_ultra"], "Abonnement : les 4 offres ETO, rien d'autre : %s" % cards)
    txt = pg.inner_text("#tool-plans .pl-list") + pg.inner_text("#tool-plans .pl-test")
    check("Standard Edition" not in txt and "Dev" not in pg.evaluate("[...document.querySelectorAll('#tool-plans .pl-chip')].map((c) => c.textContent).join(' ')") and pg.locator("#tool-plans .pl-chip").count() == 4, "les éditions privées n'apparaissent pas dans l'Abonnement")
    prices = pg.evaluate("[...document.querySelectorAll('#tool-plans .pl-price b')].map((b) => b.textContent)")
    check(prices == ["0", "2,99", "9,99", "119,99"], "prix mensuels de 0 à 119,99 € : %s" % prices)
    free = pg.inner_text('#tool-plans .pl-card[data-p="eto_free"]')
    check("Tous les échecs" in free and "Chess Edit" in free and pg.locator("#tool-plans .pl-roi").count() == 4, "ETO Free contient tous les échecs ; chaque offre dit ce qu'elle rapporte")
    pg.click('#tool-plans .pl-period button[data-a="1"]'); pg.wait_for_timeout(800)
    check(pg.inner_text('#tool-plans .pl-card[data-p="eto_pro"] .pl-price b') == "2,39" and "28,70" in pg.inner_text('#tool-plans .pl-card[data-p="eto_pro"] .pl-bill'), "annuel : ETO Pro à 2,39 €/mois (28,70 € par an)")
    pg.click('#tool-plans .pl-chip[data-sim="eto_free"]'); pg.wait_for_timeout(400)
    check(pg.locator(".pl-burst").count() == 1, "animation d'activation")
    pg.wait_for_timeout(1700)
    check(brand() == "E.T.O." and pg.evaluate("ENOS.plans.current()") == "eto_free", "ETO Free simulé : en-tête « E.T.O. » (%s)" % brand())
    check(pg.locator('#tool-plans .pl-card[data-p="eto_free"] .pl-act').count() == 1 and pg.locator("#tool-plans .pl-act").count() == 1, "badge « Actif » sur ETO Free seulement")
    check("152" in pg.evaluate("getComputedStyle(document.documentElement).getPropertyValue('--red')"), "couleur verte d'ETO Free appliquée")
    pg.click('#tool-plans .pl-card[data-p="eto_ultra"] .pl-go'); pg.wait_for_selector("#sheet:not([hidden])")
    check("Aucun montant n'est prélevé" in pg.inner_text("#sheet"), "« Choisir » : explique que le paiement arrive avec le Play Store (rien n'est prélevé)")
    pg.evaluate("ENOS.ui.closeSheet(true)")
    # Espace CEO : les 3 éditions privées + le simulateur complet
    open_tool(pg, "ceo"); pg.wait_for_timeout(900)
    priv = pg.evaluate("[...document.querySelectorAll('#tool-ceo .pl-card')].map((c) => c.dataset.p)")
    check(priv == ["enos_std", "enos_dev", "enos_ceo"] and pg.locator("#tool-ceo .pl-chip").count() == 7, "Espace CEO : Standard Edition, Dev, CEO + simulateur des 7 versions : %s" % priv)
    pg.click('#tool-ceo .pl-chip[data-sim="enos_dev"]'); pg.wait_for_timeout(1900)
    check(brand() == "E.N.O.S." and pg.locator('#tool-ceo .pl-card[data-p="enos_dev"] .pl-act').count() == 1, "E.N.O.S. Dev simulé : en-tête « E.N.O.S. », badge « Actif »")
    pg.click("#tool-ceo .pl-reset"); pg.wait_for_timeout(1900)
    check(pg.evaluate("ENOS.plans.current()") == "enos_ceo", "« Revenir à ma vraie version » : E.N.O.S. CEO")
    pg.screenshot(path=(os.environ.get("SHOTS") or "/tmp") + "/plans_ceo.png")
    # application grand public (pas l'app de test, pas de paquet CEO) : ni Espace CEO, ni simulateur
    pg.evaluate("ENOS.native.isTestBuild = () => false; ENOS.store.del && ENOS.store.del('ceo.done'); ENOS.plans.apply(true); ENOS.hub.refresh && ENOS.hub.refresh()")
    check(pg.evaluate("ENOS.plans.current()") == "eto_free" and not pg.evaluate("ENOS.plans.ceoSpace()"), "grand public : ETO Free, pas d'Espace CEO")
    pg.evaluate("ENOS.ui.go('tools'); ENOS.tools.show('')"); pg.wait_for_timeout(400)
    pg.evaluate("ENOS.hub.openCat('parametres')"); pg.wait_for_timeout(1200)
    check(pg.locator('.hub-tile[data-id="ceo"]').count() == 0 and pg.locator('.hub-tile[data-id="plans"]').count() == 1, "grand public : la tuile Espace CEO est absente, Abonnement présent")
    check(brand() == "E.T.O.", "grand public : l'en-tête dit « E.T.O. »")
    check(not errs, "aucune erreur JS : %s" % errs[:3])
    b.close()
raise SystemExit(1 if BAD else 0)
